// Beginner explanations for frequent bioinformatics workflows.
export const workflowLessons={
 genomics:['FASTQ 保存读段序列和每个碱基的质量。先看低质量尾部、接头与污染，再决定处理规则；过度剪切也会损失可用序列。','比对把读段放到参考坐标，BAM/CRAM 保存位置和质量。同一读段能落在多个重复区域时，位置并不确定；覆盖图能发现没测到的区域。','候选变异需要多个可靠分子支持。SNV 是单碱基变化，indel 是小插入缺失，SV 是较大结构改变，通常需要相应的调用方法。','VCF 中一行是候选位点，不是一条已经确定的致病结论。先核对过滤与注释，再结合遗传模式、群体频率和独立证据解释。'],
 'cancer-genomics':['匹配正常样本帮助识别个体原有的胚系变异。首先用样本身份信息检查是否配错，同时记录肿瘤纯度和取样位置。','肿瘤与正常都需要足够覆盖。重复读段不等于独立分子支持；正常样本覆盖不足时，不能只因未检出就认定为肿瘤特有。','体细胞调用比较两份证据；CNV 分析估计片段拷贝数。VAF 的分母是测得等位读段，纯度、倍性和拷贝数都会改变它。','将 SNV、CNV、结构变异与样本背景合看。亚克隆是基于模型的推断；有候选驱动变异不代表已证明该样本的功能机制。'],
 transcriptomics:['确认链特异性可帮助把读段归到正确基因。rRNA 残留过多会占用测序量；样本表要同时保留分组、供者、批次和配对信息。','比对法把读段定位到基因组，转录本定量法估计转录本来源。两种路径对注释与多重归属的处理不同，应记录参考和版本。','基因×样本矩阵的每列是一份样本。先看文库大小、样本相关和 PCA，检查标签错误、离群与批次；不要为得到分组而随意删样本。','设计矩阵告诉统计模型比较什么并控制哪些因素。先看效应方向、大小与校正 P 值，再做通路解释；TPM 不能直接替代计数模型所需的原始计数。'],
 'isoform-omics':['短读长常提供局部连接证据，长读长能连接较远的外显子。先确认完整性、接头和错误模式，避免把断裂或拼接伪影当成新转录本。','跨外显子连接的读段支持剪接位置。一个连接的支持不等于整条转录本已被观察到，尤其是多个远端事件需要配对时。','GTF 描述外显子和转录本坐标。重建候选结构后，再检查多分子支持和注释一致性；结构发现与准确计数是不同任务。','先区分基因总表达变化与异构体比例变化。PSI 描述事件包含程度，其计算依读段模型；总表达相同仍可有剪接切换。'],
 'smallrna-omics':['小 RNA 很短，测序经常读到建库接头。先识别接头并检查剪后长度分布；直接统一截短会改变成熟片段及末端变体。','rRNA、tRNA 及重复来源读段可能同时匹配多个位置。决定保留、分配或排除的规则，并说明这会如何影响目标类别。','成熟 miRNA、前体及 isomiR 的统计单位不同。先决定要回答哪一层的问题，再产生序列或类别×样本计数表。','差异表达提示候选小 RNA。靶标预测与表达反相关只能提出线索，直接调控需要报告基因、结合或干预等适配证据。'],
 epigenomics:['表观组学包含多种测量。ATAC 问哪里容易接近，ChIP/CUT&Tag 问特定靶标关联在哪里，DNA 甲基化问哪些位点被修饰；先选对读数。','轨迹是沿基因组坐标的信号。检查对照、富集、重复一致性和抗体表现；相同高度不保证不同实验具有相同分子含义。','峰是相对背景富集的区域。某些标记是窄峰，另一些形成宽区域；峰调用模型与靶标特征应匹配。','在共同区域集合上比较重复样本。把峰关联到邻近基因可产生假设，但增强子可能作用于较远基因，仍需额外证据。'],
 chromatinomics:['ATAC 片段长度、TSS 富集和可用片段数从不同角度反映质量。MNase 的消化程度又会影响保护片段，不能沿用完全相同的判断。','去除不可靠比对和适当处理重复后得到片段集合。是否去掉线粒体等片段，应结合实验目的和标准化流程。','ATAC 峰描述相对开放区域；MNase 保护片段提供核小体相关信息。得到的 BED 区域或 bigWig 轨迹需注明参考基因组。','motif 是候选识别序列，不是实测结合。结合表达、靶标定位和干预信息，才能逐步从可及性走向调控解释。'],
 methylomics:['转化测序通过碱基变化读取修饰状态。检查转化对照，转化不完全可能被误判为修饰；不同化学方法应使用相应评估。','比对软件需要考虑转化后的碱基规则。普通 DNA 比对逻辑不能直接照搬；正负链与重复区域也会影响位点归属。','某 CpG 的比例来自修饰读段数除以有效覆盖数。1/1 和 50/100 的比例不同、证据量也不同；无覆盖应记为缺失。','DMP 关注位点，DMR 关注一段区域。比较时考虑重复、覆盖和细胞组成；传统亚硫酸氢盐结果不能自动区分 5mC 与 5hmC。'],
 'threed-genomics':['Hi-C 的一对读段提供两个基因组位置的信息。先识别有效连接并去除实验伪影，否则矩阵中的亮点可能来自技术背景。','把两个读段端点放到一致的基因组坐标，再生成有效接触配对。检查重复率和染色体内外接触构成。','矩阵的行列是基因组区间，格子是接触计数。小 bin 更细，但需要足够数据；低覆盖区间可能影响矩阵平衡。','线性距离近的区域本来就更容易接触。识别候选环需对照背景；热图亮点不是直接测得的固定三维距离。'],
 'singlecell-omics':['从 FASTQ 和条码结构出发，区分 cell barcode 与 UMI：前者追踪细胞，后者辅助识别同一原始分子的扩增重复。','细胞筛选结合基因数、UMI、线粒体比例、环境 RNA 和双细胞线索。阈值因组织而异，不能机械删除某一种细胞状态。','归一化、特征选择和降维帮助比较细胞。聚类是相似性分组，需结合多种标记与背景注释；UMAP 坐标不直接表示真实空间。','比较处理组时，要回到独立供者或样本单位。可以按供者和细胞类型汇总 pseudobulk，再使用适配设计，避免把细胞数当独立重复数。'],
 'singlecell-atac':['fragments 文件记录带条码的基因组片段。先看有效片段、TSS 富集、片段长度与双细胞，核质量会影响整体信号。','定义可比较的峰集合后统计峰×细胞矩阵。峰集合不同会改变 FRiP 与计数，样本之间应保持坐标和处理规则一致。','稀疏峰矩阵常用 TF-IDF 与 LSI 等处理。低维分组依测量深度与生物差异共同影响，需检查技术因素。','motif 富集、gene activity 和峰—基因联系属于推断层。它们可提出候选调控者，但不能替代直接结合或实际 RNA 测量。'],
 'singlecell-multiome':['分别核查 RNA 的基因/UMI、ATAC 的片段/TSS 或 ADT 的背景。一个细胞的某种模态好，不保证其他模态同样合格。','细胞条码和样本身份是配对钥匙，文件行号不是。先求出可可靠配对的细胞集合，再记录丢失模态或筛选的原因。','每种模态使用适配的归一化和降维，随后选择整合策略。WNN 学习模态贡献，不能理解为直接相加原始 RNA 与蛋白数值。','联合图谱之后分别检查各模态证据。ADT 只测抗体面板，RNA–ATAC 的关联也不单独证明某个峰直接调控该基因。'],
 'spatial-omics':['记录组织、切片、样本与位置坐标。成像式平台和捕获式平台的原始文件不同；先明确测量单位是 spot、分子还是分割细胞。','检查图像和表达坐标的配准，确认组织边界与质量区域。分割错误可能把相邻细胞信号合并或切开。','在空间单位上归一化并比较表达，必要时结合参考做细胞组成推断。一个 spot 可混合多个细胞，标签未必是纯细胞类型。','检验空间模式需考虑邻接关系和独立样本。细胞邻近、配体受体共表达可以提出通信线索，但还不是实际通信的功能证明。'],
 'immune-repertoire':['V(D)J 数据需要识别受体序列、CDR3 与链型。先检查 productive 等质量字段及链检出，原始读段数不总等于细胞数。','单细胞数据可按条码连接受体链，bulk 通常难保留配对。多条链可能来自生物现象或双细胞，需结合规则处理。','克隆定义要说明使用哪些链、核酸还是氨基酸，以及相似度规则。规则不同会改变克隆数和多样性。','将克隆大小与样本、时间和表达状态对应。相对比例上升可来自其他克隆减少；抗原特异性还需可靠的额外证据。'],
 proteomics:['原始谱图与样本表应对应，并保留空白、QC 和采集方式。色谱漂移、仪器批次和定量缺失会影响后续比较。','将碎片谱与候选肽段匹配，或使用适配 DIA 的分析。搜索库、修饰与酶切规则决定候选空间，不能沿用不匹配的默认设置。','PSM 是谱图与肽段匹配，随后才是肽段与蛋白层。各层错误率分别控制；共享肽可能让多个蛋白无法独立区分。','检查缺失模式再选择处理方法，避免把所有缺失直接填零。结合独立重复比较蛋白，鉴定 FDR 与差异检验 FDR 属于不同问题。'],
 phosphoproteomics:['磷酸肽富集增加低丰度修饰的覆盖，但富集效率会影响信号。最好配套总蛋白组，以区分修饰载体增加和位点变化。','鉴定为磷酸肽不等于知道修饰落在哪个残基。一个肽可有多个候选位点，需要查看定位置信度与碎片支持。','位点信号通常反映相对量。若总蛋白也变化，需联合解释；简单比值教学不等于获得绝对修饰占有率。','底物集合能提供候选激酶活性线索。检查覆盖、位点方向与先验集合，再用适配功能实验验证。'],
 metabolomics:['一个特征通常以 m/z 和保留时间定位。先找峰并校正漂移，跨样本对齐后才可比较同一候选信号。','空白能揭示背景，混合 QC 能显示仪器漂移。过滤规则应预先合理设定，避免把真实低丰度信号与污染一概处理。','加合物、同位素和碎片会使同一化合物产生多个特征。谱库与标准品提供不同强度的身份支持，报告相应鉴定层级。','比较前检查内标、批次和缺失。通路分析依赖可靠身份；未知特征 F1 不能直接作为已确认的某个代谢物。'],
 microbiomics:['扩增子是选择性放大的一段标记，16S/ITS 引物会影响能看到的成员。阴性对照尤其有助于判断低生物量污染。','去噪和去嵌合体生成 ASV，即精确扩增子序列变体。ASV 不是天然物种标签，需要后续分类。','特征表列为样本，行为 ASV。分类结果受区域和参考数据库限制，不一定能达到物种级；保留未确定层级。','多样性和差异分析要考虑测序深度、组成性及配对设计。某成员占比增加，不能单独证明它的绝对数量增加。'],
 metagenomics:['shotgun 测混合 DNA，可含大量宿主序列。先质控并按方案去宿主，保留处理记录，再评估有效微生物覆盖。','分类谱路线估计成员组成；组装路线连接读段形成 contig。两条路线回答互补问题，并非每个项目都必须先组装。','基因注释提出功能潜力，分箱把 contig 归入候选 MAG。评估完整度与污染度，同时关注近缘菌株混合带来的困难。','跨样本比较要统一参考与定量单位。发现某功能基因代表潜力，不能仅凭 DNA 证明它在当前条件下被表达或发挥功能。'],
 metatranscriptomics:['群落 RNA 常含大量 rRNA，去除效率决定有多少读段用于功能分析。样本保存、提取与 RNA 稳定性尤其重要。','宿主、rRNA 与目标转录本的处理需要明确分流。建立适合样本的参考，复杂群落中的保守基因可能无法唯一归属。','将计数汇总到基因家族或通路，并保留物种归属的不确定性。不同数据库注释体系需要建立清楚对应关系。','RNA 上升可能因为某成员更多，也可能因为单位成员表达更强。配套宏基因组可提供背景，但归一化与组成性仍需审慎设计。']
};
export const bioGlossary=[['FASTQ','测序读段及碱基质量，像尚未放回地图的一包短句。'],['FASTA / GTF','FASTA 保存参考序列；GTF 描述基因、外显子等坐标。'],['BAM / CRAM','读段比对到参考后的记录；相同位置可能有多条支持。'],['计数矩阵','行是基因、峰等特征，列是样本或细胞；先问清每行每列是什么。'],['归一化','处理测序量或可比尺度差异；不会自动消除批次混杂。'],['FDR','控制一组发现中的预期错误发现比例；不是某个结果出错的概率。']];
